//! 🧳️ Genuine original child admission closes before a borrowed vector graph becomes available.
use super::*;
use crate::admission::{ChildAdmissionRead,EmbeddedChildAdmission};
use semio_framework_value::retained_clone::RetainedCloneBinding;
#[derive(Clone,Copy,PartialEq,Eq)]enum Phase{Source,Birth,Admit,Retire,Ready,Refused,Closed}
pub struct OriginalChildVectorAdvance<'a>{pub progress:RetainedCloneProgress,pub done:bool,pub error:Option<&'static str>,pub canvas:Option<VectorCanvas>,pub graph:Option<&'a dyn VectorGraphSourceV1>}
pub struct OriginalChildVectorPreparation{binding:Option<RetainedCloneBinding>,admitter:Option<&'static dyn EmbeddedChildAdmitterV1>,vector:Option<&'static dyn EmbeddedChildVectorSourceV1>,admission:Option<EmbeddedChildAdmission>,phase:Phase,closing:bool,error:Option<&'static str>,canvas:Option<VectorCanvas>}
impl OriginalChildVectorPreparation{
 const HEADER:usize=std::mem::size_of::<Self>()*2;
 fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:Self::HEADER,depth:1,..Default::default()}}
 pub fn birth_demand()->RetirementDemand{Self::fixed()}
 pub fn admit(g:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),ValueError>{let d=Self::birth_demand();if !retained_clone_grant_admits(g,d){return Err(refusal("Original child vector preparation birth is unfunded"))}Ok((Self{binding:None,admitter:None,vector:None,admission:None,phase:Phase::Source,closing:false,error:None,canvas:None},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 fn nested(d:RetirementDemand)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:d.copy_bytes.checked_add(Self::HEADER).ok_or_else(||refusal("Original child vector demand overflow"))?,depth:d.depth.checked_add(1).ok_or_else(||refusal("Original child vector depth overflow"))?,..d})}
 fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.saturating_sub(Self::HEADER),maximum_depth:g.maximum_depth.saturating_sub(1),..g}}
 fn paid(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_items=p.copied_items.max(1);p.copied_bytes=p.copied_bytes.saturating_add(Self::HEADER);p}
 fn failure(error:ValueError)->ValueError{let p=Self::paid(error.retained_progress());error.with_retained_progress(p)}
 fn accept(p:RetainedCloneProgress,g:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{if !p.fits(g){return Err(refusal("Original child vector receipt exceeds the remaining grant").with_retained_progress(Self::paid(p)))}Ok(Self::paid(p))}
 fn verify(&self,read:&ChildAdmissionRead<'_>)->Result<(),ValueError>{if let Some(expected)=self.admitter{if !std::ptr::eq(expected,read.admitter){return Err(refusal("Original child vector admitter changed"))}}if let Some(expected)=self.vector{if !std::ptr::eq(expected,read.vector){return Err(refusal("Original child vector producer changed"))}}if self.binding.is_some(){read.source.binding_demand(&self.binding)?;}Ok(())}
 pub fn next_demand(&self,read:&ChildAdmissionRead<'_>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.phase==Phase::Closed{return Err(refusal("Original child vector preparation is closing"))}self.verify(read)?;match self.phase{Phase::Source=>Self::nested(read.source.binding_demand(&self.binding)?.unwrap_or_default()),Phase::Birth=>Self::nested(read.admitter.birth_demand()),Phase::Admit=>Self::nested(self.admission.as_ref().unwrap().next_demand(read.source,body.saturating_sub(Self::HEADER))?),Phase::Retire=>Self::nested(self.admission.as_ref().unwrap().close_demand(body.saturating_sub(Self::HEADER))?),Phase::Ready=>Self::nested(read.vector.read_demand()),_=>Ok(Self::fixed())}}
 pub fn advance<'a>(&mut self,read:&ChildAdmissionRead<'a>,g:RetainedCloneGrant)->Result<OriginalChildVectorAdvance<'a>,ValueError>{let d=self.next_demand(read,g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(OriginalChildVectorAdvance{progress:Default::default(),done:false,error:None,canvas:None,graph:None})}let c=Self::child(g);let mut out=OriginalChildVectorAdvance{progress:Default::default(),done:false,error:None,canvas:None,graph:None};match self.phase{
 Phase::Source=>{out.progress=read.source.bind(&mut self.binding,c).map_err(Self::failure)?.unwrap_or_default();self.admitter=Some(read.admitter);self.vector=Some(read.vector);self.phase=Phase::Birth;},
 Phase::Birth=>{let (cursor,p)=read.admitter.begin(c).map_err(Self::failure)?;self.admission=Some(cursor);out.progress=p;self.phase=Phase::Admit;},
 Phase::Admit=>{let step=self.admission.as_mut().unwrap().advance(read.source,c).map_err(Self::failure)?;out.progress=step.progress;if step.canvas.is_some(){self.canvas=step.canvas}if step.done{self.error=step.error;self.admission.as_mut().unwrap().begin_close();self.phase=Phase::Retire}},
 Phase::Retire=>{let cursor=self.admission.as_mut().unwrap();out.progress=cursor.close_step(c).map_err(Self::failure)?.progress();if cursor.terminal_is_empty(){self.admission=None;self.phase=if self.error.is_none(){Phase::Ready}else{Phase::Refused}}},
 Phase::Ready=>{let step=read.vector.read(read.source,c).map_err(Self::failure)?;if step.done!=step.graph.is_some(){return Err(refusal("Child vector completion and graph custody disagree").with_retained_progress(Self::paid(step.progress)))}out.progress=step.progress;out.done=step.done;out.graph=step.graph;out.canvas=self.canvas;},
 Phase::Refused=>{out.done=true;out.error=self.error;},
 Phase::Closed=>unreachable!()};out.progress=Self::accept(out.progress,c)?;Ok(out)}
 pub fn begin_close(&mut self){self.closing=true;if let Some(cursor)=self.admission.as_mut(){cursor.begin_close()}}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.phase==Phase::Closed{return Ok(Default::default())}if let Some(cursor)=self.admission.as_ref(){return Self::nested(cursor.close_demand(body.saturating_sub(Self::HEADER))?)}if self.binding.is_some(){return Self::nested(RetainedCloneBinding::close_demand(&self.binding,body.saturating_sub(Self::HEADER))?)}Ok(Self::fixed())}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(refusal("Original child vector closure has not begun"))}if self.phase==Phase::Closed{return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let c=Self::child(g);let p=if let Some(cursor)=self.admission.as_mut(){let p=cursor.close_step(c).map_err(Self::failure)?.progress();if cursor.terminal_is_empty(){self.admission=None;}p}else if self.binding.is_some(){RetainedCloneBinding::close_one(&mut self.binding,c).map_err(Self::failure)?.progress()}else{self.admitter=None;self.vector=None;self.error=None;self.canvas=None;self.phase=Phase::Closed;Default::default()};let p=Self::accept(p,c)?;Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn terminal_is_empty(&self)->bool{self.phase==Phase::Closed&&self.binding.is_none()&&self.admission.is_none()&&self.admitter.is_none()&&self.vector.is_none()}
}
impl Drop for OriginalChildVectorPreparation{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Original child vector preparation requires funded child and original-source closure")}}
